package com.commercecore.order;import com.commercecore.inventory.InventoryReservation;import com.commercecore.product.*;import jakarta.persistence.*;import java.math.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="order_items")public class OrderItem{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_id",nullable=false)private CustomerOrder order;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="source_product_id")private Product sourceProduct;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="source_variant_id")private ProductVariant sourceVariant;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="inventory_reservation_id",unique=true)private InventoryReservation inventoryReservation;@Column(name="product_name",nullable=false,length=200)private String productName;@Column(nullable=false,length=64)private String sku;@Column(nullable=false)private int quantity;@Column(name="unit_price",nullable=false,precision=19,scale=2)private BigDecimal unitPrice;@Column(name="line_subtotal",nullable=false,precision=19,scale=2)private BigDecimal lineSubtotal;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@OneToMany(mappedBy="orderItem",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("displayOrder ASC, name ASC")private final List<OrderItemAttribute>attributes=new ArrayList<>();protected OrderItem(){}public OrderItem(CustomerOrder order,Product p,ProductVariant v,int quantity,BigDecimal unit){this.order=order;sourceProduct=p;sourceVariant=v;productName=p.getName();sku=v==null?p.getSku():v.getSku();if(quantity<1||quantity>99)throw new IllegalArgumentException();this.quantity=quantity;unitPrice=unit.setScale(2,RoundingMode.HALF_UP);lineSubtotal=unitPrice.multiply(BigDecimal.valueOf(quantity)).setScale(2,RoundingMode.HALF_UP);if(v!=null)for(VariantAttribute a:v.getAttributes())attributes.add(new OrderItemAttribute(this,a.getName(),a.getValue(),a.getDisplayOrder()));}public void linkReservation(InventoryReservation r){if(inventoryReservation!=null)throw new IllegalStateException();inventoryReservation=Objects.requireNonNull(r);}@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public CustomerOrder getOrder(){return order;}public Product getSourceProduct(){return sourceProduct;}public ProductVariant getSourceVariant(){return sourceVariant;}public InventoryReservation getInventoryReservation(){return inventoryReservation;}public String getProductName(){return productName;}public String getSku(){return sku;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getLineSubtotal(){return lineSubtotal;}public Instant getCreatedAt(){return createdAt;}public List<OrderItemAttribute>getAttributes(){return attributes;}}
